public string Multiply(string num1, string num2)
{
    if (num1 == "0" || num2 == "0") return "0";
    int n = num1.Length, m = num2.Length;
    int[] pos = new int[n + m];
    for (int i = n - 1; i >= 0; i--)
    {
        for (int j = m - 1; j >= 0; j--)
        {
            int mul = (num1[i] - '0') * (num2[j] - '0');
            int p1 = i + j, p2 = i + j + 1;
            int sum = mul + pos[p2];
            pos[p2] = sum % 10;
            pos[p1] += sum / 10;
        }
    }
    var sb = new StringBuilder();
    foreach (var d in pos) if (sb.Length > 0 || d != 0) sb.Append(d);
    return sb.ToString();
}
